#!/usr/bin/env python3
"""Read-only P0 resource and compatibility ledger for the frozen K210 target."""
from __future__ import annotations
import hashlib, json, os, struct
from pathlib import Path
import h5py, numpy as np

ROOT=Path(__file__).resolve().parents[1]
EDGE=Path('/home/quyet/edge_ai_project')
OUT=ROOT/'reports/full_pipeline_resource'

def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def tagged(value,label,note=''): return {'value':value,'label':label,'note':note}
def kb(n): return f'{n:,} B ({n/1024:.2f} KiB)'
def binary_count(path):
    with open(path,'rb') as f:return struct.unpack('<Q',f.read(8))[0]

def package_audit(name):
    base=EDGE/'map_packages'/name; glob=base/'features/global-feats-v2-mixvpr.h5'; idx=base/'indexes/point3d-index-refined_model_v2.npz'; col=base/'colmap/refined_model_v2'
    rows=[]
    with h5py.File(glob,'r') as f:
        def visit(k,v):
            if isinstance(v,h5py.Dataset) and k.endswith('global_descriptor'):
                rows.append({'name':k,'shape':list(v.shape),'dtype':str(v.dtype),'logical_bytes':v.size*v.dtype.itemsize,'stored_bytes':v.id.get_storage_size()})
        f.visititems(visit)
    z=np.load(idx,allow_pickle=False)
    arrays=[{'name':k,'shape':list(z[k].shape),'dtype':str(z[k].dtype),'bytes':int(z[k].nbytes)} for k in z.files]
    files={x:os.path.getsize(col/x) for x in ('cameras.bin','images.bin','points3D.bin')}
    return {'package':name,'base':str(base),'global_db':{'path':str(glob),'file_bytes':os.path.getsize(glob),'reference_count':len(rows),'descriptors':rows,'logical_descriptor_bytes':sum(x['logical_bytes'] for x in rows),'stored_descriptor_bytes':sum(x['stored_bytes'] for x in rows),'non_descriptor_file_bytes':os.path.getsize(glob)-sum(x['stored_bytes'] for x in rows)},'point3d_index':{'path':str(idx),'file_bytes':os.path.getsize(idx),'arrays':arrays},'colmap':{'dir':str(col),'file_bytes':files,'counts_from_binary_headers':{'images':binary_count(col/'images.bin'),'points3D':binary_count(col/'points3D.bin'),'cameras':binary_count(col/'cameras.bin')}}}

def superpoint():
    paths={'160x120':ROOT/'reports/superpoint_resolution_gate/r2_160_export.json','192x144':ROOT/'reports/superpoint_resolution_gate/r1_export_192x144.json'}
    output={}
    for res,p in paths.items():
        d=json.loads(p.read_text()); act=d['logical_activations'];by={x['name']:x for x in act}; model=ROOT/'artifacts'/f'superpoint_k210_v1_fr12_l1init_{res}.kmodel'
        output[res]={'export_report':str(p),'input_shape':d['input_shape'],'detector_shape':d['detector_shape'],'descriptor_shape':d['descriptor_shape'],'largest_logical_fp32_bytes':d['largest_logical_fp32_activation_bytes'],'largest_logical_int8_bytes':max(x['projected_int8_bytes'] for x in act),'detector_dense':by['detector_logits'],'descriptor_dense':by['descriptor_map'],'kmodel_path':str(model),'kmodel_bytes':model.stat().st_size,'kmodel_sha256':sha(model)}
    return output

def retrieval_work(block):
    # Actual DB is FP16; streaming-stage arithmetic conversion is deliberately not assumed.
    return 4096*4 + block*4096*2 + block*4 + 9*(4+4)

def feature_bytes(k,desc_bytes): return k*(2*4+4+256*desc_bytes)
def matching_stream(nq,nr,b): return feature_bytes(nq,4)+b*256*4+nq*(4+4+4+4)+nr*(4+4)+b*4

def pnp_bytes(n): return {'pts2d_f64':n*2*8,'pts3d_f64':n*3*8,'scores_f32':n*4,'point_ids_i64':n*8,'inlier_mask_u8_estimated':n,'correspondence_indices_i32_pair':n*2*4}

def build_manifest():
    p6,p7=package_audit('floor6_v1'),package_audit('floor7_v1')
    m03=json.loads((ROOT/'reports/mixvpr_feasibility/m03_dtype_canonical_compiler.json').read_text())
    m01=json.loads((ROOT/'reports/mixvpr_feasibility/m01_static_core_manifest.json').read_text())
    m01g=json.loads((ROOT/'reports/mixvpr_feasibility/m01_static_core_graph.json').read_text())
    sp=superpoint()
    features={str(k):{'fp32_descriptor_bytes':feature_bytes(k,4),'int8_comparison_bytes':feature_bytes(k,1)} for k in (256,512,1024)}
    matcher={'full_similarity_fp32':{f'{q}x{r}':q*r*4 for q in (256,512,1024) for r in (256,512,1024,2048,4096,8192)},'streaming_fp32':{f'Nq={q},Nr={r},block={b}':matching_stream(q,r,b) for q in (256,512,1024) for r in (256,512,1024,2048,4096,8192) for b in (16,32,64)}}
    return {'protocol_version':'P0-v1','scope':'Read-only resource/compatibility audit; no benchmark/model/source-project rerun or modification.',
      'number_labels':['MEASURED','COMPILER_REPORTED','DERIVED_EXACT','ESTIMATED','UNKNOWN'],
      'frozen_target':{'mixvpr_core_input':[1,3,320,320],'mixvpr_output':[1,4096],'superpoint_primary':'160x120 V1-FR12','superpoint_fallback':'192x144 V1-FR12','online_excludes':'LightGlue'},
      'mixvpr':{'parameters':tagged(m01['unchanged_core']['parameter_count'],'DERIVED_EXACT'),'fp32_parameter_bytes':tagged(m01['unchanged_core']['fp32_parameter_bytes'],'DERIVED_EXACT'),'int8_parameter_bytes_theoretical':tagged(m01['unchanged_core']['parameter_count'],'DERIVED_EXACT'),'input_fp32_bytes':tagged(1*3*320*320*4,'DERIVED_EXACT'),'descriptor_fp32_bytes':tagged(4096*4,'DERIVED_EXACT'),'descriptor_int8_comparison_bytes':tagged(4096,'DERIVED_EXACT'),'largest_logical':tagged(m01g['largest_logical_activation'],'DERIVED_EXACT','Individual logical tensor, not peak RAM.'),'largest_backbone_logical':tagged(m01g['largest_backbone_logical_activation'],'DERIVED_EXACT','Individual logical tensor, not peak RAM.'),'largest_aggregator_logical':tagged(m01g['largest_aggregator_logical_activation'],'DERIVED_EXACT','Individual logical tensor, not peak RAM.'),'compiler':m03},
      'maps':{'floor6':p6,'floor7':p7,'selection_note':'Both existing current packages were measured. A board uses one package at a time; Floor 6 has the larger Point3D index and Floor 7 has the larger global DB.'},
      'superpoint':sp,'selected_feature_storage':features,'retrieval_streaming_work':{str(b):retrieval_work(b) for b in (8,16,32,64)},'matching':matcher,'pnp':{str(n):pnp_bytes(n) for n in (32,64,128,256)},
      'camera':{'capture_frame':tagged(None,'UNKNOWN','Camera/DVP sensor format and capture resolution are not frozen.'),'rgb565':tagged(None,'UNKNOWN','Only plausible if sensor is configured RGB565; shape unavailable.'),'rgb888_320x320':tagged(320*320*3,'DERIVED_EXACT','Derived only for a 320x320 RGB888 resize staging buffer.'),'mixvpr_fp32_input_320x320':tagged(320*320*3*4,'DERIVED_EXACT'),'superpoint_gray_160x120':tagged(160*120,'DERIVED_EXACT'),'superpoint_gray_192x144':tagged(192*144,'DERIVED_EXACT')},
      'source_logic':{'point_index':'localize_edge_v3.py:627 Point3DDescriptorIndex; current Python constructor loads descriptors/xyz/point_ids and casts descriptors to FP32, point IDs I64.','matching':'localize_edge_v3.py:741 correspondences(): score threshold, optional best-vs-second margin, best_by_point, strongest max_matches.','covisibility':'localize_edge_v3.py:987 build_covisibility_graph(): currently derives graph from full pycolmap Reconstruction at startup.','pnp':'localize_edge_v3.py:865/1340 pycolmap.estimate_and_refine_absolute_pose.'}}

